-- ¿Qué migraciones ya corrí? Pégala completa en Supabase → SQL Editor y toca Run.
-- Solo lee, no cambia nada. Corre en orden las que digan FALTA (cualquiera de 0012 a 0042 se puede repetir sin daño).
select m.archivo,
       case when m.aplicada then 'Ya está' else 'FALTA: córrela' end as estado
from (values
  (1, '0012_seguridad.sql',           to_regprocedure('public.is_api_role()') is not null),
  (2, '0013_acceso_comunidad_retos.sql', to_regprocedure('public._has_app_access(uuid)') is not null),
  (3, '0014_multiusuario.sql',        to_regprocedure('public.can_see_post(bigint)') is not null or exists (select 1 from pg_proc where proname = 'can_see_post')),
  (4, '0015_nutricion.sql',           to_regclass('public.saved_foods') is not null),
  (5, '0016_admin_dueno.sql',         exists (select 1 from auth.users u join public.profiles p on p.id = u.id where lower(u.email) = 'andresguevarag@hotmail.com' and p.role::text = 'superadmin')),
  (6, '0017_mis_recetas.sql',         to_regclass('public.user_recipes') is not null),
  (7, '0018_tienda_retos.sql',        to_regclass('public.challenge_purchases') is not null),
  (8, '0019_comunidad_tribu.sql',     exists (select 1 from pg_proc where proname = 'community_board')),
  (9, '0020_dueno_siempre_admin.sql', exists (select 1 from pg_proc where proname = 'handle_new_user' and prosrc ilike '%andresguevarag@hotmail.com%') or to_regprocedure('public.rate_hit(text,integer,integer)') is not null),
  (10,'0021_periodo_prueba.sql',      exists (select 1 from pg_proc where proname = '_has_app_access' and (prosrc like '%2026-11-01%' or prosrc like '%_beta_ends_at()%'))),
  (11,'0022_acceso_nutricion.sql',    to_regprocedure('public.has_nutrition_access()') is not null and exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'meals' and policyname = 'meals: crear propias con nutrición')),
  (12,'0023_seguridad_2.sql',         to_regprocedure('public.rate_hit(text,integer,integer)') is not null and to_regprocedure('public.scrub_deleted_user(uuid)') is not null and not exists (select 1 from pg_proc where proname = 'handle_new_user' and prosrc ilike '%andresguevarag@hotmail.com%')),
  (13,'0024_programas.sql',           to_regclass('public.user_programs') is not null and to_regclass('public.program_sessions') is not null and to_regprocedure('public.program_start(text,date,boolean)') is not null and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'challenges_catalog' and column_name = 'kind')),
  (14,'0025_regalos_referidos.sql',   to_regclass('public.referrals') is not null and to_regprocedure('public.admin_gift_months(uuid,text,integer,text,text)') is not null and to_regprocedure('public._beta_ends_at()') is not null and exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'workouts' and policyname = 'workouts: crear con plan')),
  (15,'0026_tarjeta_prueba.sql',      to_regclass('public.payment_methods') is not null and to_regclass('public.trial_charges') is not null and to_regprocedure('public._trial_live(uuid)') is not null and exists (select 1 from pg_proc where proname = '_has_app_access' and prosrc like '%_trial_live%') and not exists (select 1 from pg_proc where proname = '_has_app_access' and prosrc like '%7 days%')),
  (16,'0027_experiencias.sql',        exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'daily_logs' and column_name = 'program_checks') and exists (select 1 from public.challenges_catalog where slug = 'banana-girl')),
  (17,'0028_retos_visual.sql',        exists (select 1 from public.challenges_catalog where slug = 'abdomen-21' and status <> 'publicado')),
  (18,'0029_testers.sql',             to_regclass('public.tester_grants') is not null and to_regclass('public.feedback_reports') is not null and to_regprocedure('public.admin_set_tester(uuid,text)') is not null and to_regprocedure('public.tester_hold_charge(uuid)') is not null and exists (select 1 from pg_proc where proname = 'admin_list_users' and prosrc like '%tester_until%')),
  (19,'0030_perfil_insignias.sql',    to_regclass('public.identity_verifications') is not null and to_regclass('public.profile_flair') is not null and to_regprocedure('public.community_flair(uuid[])') is not null and to_regprocedure('public.identity_purge_due(integer)') is not null and exists (select 1 from storage.buckets where id = 'identidad' and not public)),
  (20,'0031_guia.sql',                exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'profiles' and column_name = 'guide_tips') and to_regprocedure('public.guide_mark_seen(integer)') is not null and to_regprocedure('public.guide_tip_seen(text)') is not null),
  (21,'0032_coach_cuota.sql',        to_regclass('public.coach_quota_tickets') is not null and to_regprocedure('public.coach_take_quota(text)') is not null and to_regprocedure('public.coach_refund_quota(uuid)') is not null and to_regprocedure('public.coach_quota_status()') is not null and to_regprocedure('public.admin_coach_usage(uuid)') is not null),
  (22,'0033_retos_gratis.sql',       exists (select 1 from pg_constraint where conname = 'challenges_catalog_free_days_check')),
  (23,'0034_soporte.sql',             to_regclass('public.support_tickets') is not null and to_regclass('public.support_messages') is not null and to_regclass('public.support_events') is not null and to_regprocedure('public.support_create_ticket(text,text,text,jsonb,text)') is not null and exists (select 1 from storage.buckets where id = 'soporte' and not public)),
  (24,'0035_lenguaje.sql',            exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'profiles' and column_name = 'lenguaje') and exists (select 1 from pg_constraint where conname = 'profiles_lenguaje_check')),
  (25,'0036_novedades.sql',          exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'profiles' and column_name = 'news_seen') and to_regprocedure('public.news_mark_seen(text)') is not null),
  (26,'0037_pilates_platanita.sql',  to_regprocedure('public._program_days(jsonb)') is not null and exists (select 1 from public.challenges_catalog where slug = 'pilates-casa-30')),
  (27,'0038_seguridad_3.sql',        not has_table_privilege('authenticated', 'public.public_profiles', 'update') and not has_table_privilege('authenticated', 'public.public_profiles', 'delete') and exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'payment_events' and policyname = 'eventos de pago: leer propios o staff de cuentas')),
  (28,'0039_textos_neutros.sql',     not exists (select 1 from public.challenges_catalog where program::text like '%cuando estás listo%' or program::text like '%cuando estás fresco%') and not exists (select 1 from public.challenge_plans where days::text like '%si estás cansado%')),
  (29,'0040_escala.sql',             to_regclass('public.ai_usage_daily') is not null and to_regprocedure('public.ai_budget_take(text,integer,bigint)') is not null and to_regprocedure('public.purge_housekeeping(integer)') is not null and to_regprocedure('public.auth_user_id_by_email(text)') is not null and to_regclass('public.comments_post_created') is not null),
  (30,'0041_monitoreo.sql',          to_regclass('public.app_errors') is not null and to_regclass('public.ops_heartbeats') is not null and to_regprocedure('public.app_error_report(text,text,text,text,text,text,text,text)') is not null and to_regprocedure('public.admin_error_summary(integer)') is not null and to_regprocedure('public.app_errors_purge(integer)') is not null and to_regprocedure('public.health_ping()') is not null),
  (31,'0042_tilopay.sql',            exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'subscriptions' and column_name = 'next_renewal_attempt_at') and exists (select 1 from pg_constraint where conname = 'payment_methods_provider_ok')))
) as m(orden, archivo, aplicada)
order by m.orden;
